#!/usr/bin/env bash
# Behavior tests for the task machine (core/machines/tables/task.tsv, core/machines/observers/task.sh):
# one state per task, including stale, abandoned and finished-elsewhere, and the opt-in fleet-view column.
# The fixture home is generated by seed_home; no fleet record is copied. Readers the observer calls
# (crew state, backlog row, forge) are stand-ins in the fixture home, so each state is set by one file.
set -u
# shellcheck source=tests/lib.sh
. "$(dirname "${BASH_SOURCE[0]}")/lib.sh"

JM="$ROOT/bin/jg-machine.sh" OBS="$ROOT/core/machines/observers/task.sh"
T=$(jg_test_tmproot jg-machine-task); H=$T/home
mkdir -p "$H"/{state,config,bin,crew,rows,forge,data/jg-trunk-landing} "$T/fakebin"
export JG_HOME=$H PATH="$T/fakebin:$PATH"
cat > "$H/bin/jg-crew-state.sh" <<'SH'
#!/usr/bin/env bash
printf 'state: %s · source: none · fixture\n' "$(cat "$JG_HOME/crew/$1" 2>/dev/null || echo unknown)"
SH
cat > "$H/bin/jg-backlog.sh" <<'SH'
#!/usr/bin/env bash
[ -r "$JG_HOME/rows/$2" ] || exit 1
printf 'task:\n  id: %s\n  state: %s\n' "$2" "$(cat "$JG_HOME/rows/$2")"
SH
cat > "$T/fakebin/gh" <<'SH'
#!/usr/bin/env bash
n=; for a in "$@"; do case $a in number=*) n=${a#number=} ;; esac; done
cat "$JG_HOME/forge/$n"
SH
chmod +x "$H"/bin/*.sh "$T/fakebin/gh"

seed_task() {  # <id> <crew word> <row state> <pr number|-> <forge: open|merged|closed|-> <last status line|->
  printf '%s' "$2" > "$H/crew/$1"; printf '%s' "$3" > "$H/rows/$1"
  [ "$6" = - ] || printf '%s\n' "$6" > "$H/state/$1.status"
  printf 'kind=ship\n' > "$H/state/$1.meta"; [ "$4" = - ] && return 0
  printf 'pr=https://github.com/o/r/pull/%s\n' "$4" >> "$H/state/$1.meta"
  case $5 in
    open) printf 'state=OPEN\nmerged=false\n' ;; merged) printf 'state=MERGED\nmerged=true\n' ;;
    closed) printf 'state=CLOSED\nmerged=false\n' ;; esac > "$H/forge/$4"
}
seed_home() {
  local w n=0
  for w in working parked "done" blocked paused failed unknown; do seed_task "c-$w" "$w" "done" - - -; done
  seed_task h-open working in_flight 1 open -;  seed_task h-queued unknown queued - - -
  seed_task h-closed "done" "done" 2 merged -
  seed_task s-pr working in_flight 11 merged 'working [at=1]: x'; seed_task s-queued parked queued 13 merged -
  seed_task s-landed unknown in_flight - - -; printf 'landed abc\n' > "$H/data/jg-trunk-landing/s-landed.deadbeef.state"
  for n in 21 22 23; do seed_task "a-$n" unknown in_flight "$n" closed -; done
  seed_task f-1 "done" in_flight 31 merged 'done [at=2]: ready in branch f'
  # Local-trunk lanes: two finished and waiting (t-ready1 is older), one landed, one cleaned, one refused, one reverted, one gone.
  local d='done [at=2]: ready in branch b' h t; h=$(printf 'a%.0s' {1..40})
  for t in t-ready1 t-ready2 t-land t-clean t-final t-rev; do seed_task $t "done" in_flight - - "$d"; printf 'mode=local-trunk\n' >> "$H/state/$t.meta"; done
  touch -d '2026-01-01 00:00:01' "$H/state/t-ready1.status"; touch -d '2026-01-01 00:00:02' "$H/state/t-ready2.status"
  printf 'landed cleanup refused\n' > "$H/data/jg-trunk-landing/t-land.$h.state"; printf 'landed cleaned up\n' > "$H/data/jg-trunk-landing/t-clean.$h.state"
  printf 'final conflict in a.txt\n' > "$H/data/jg-trunk-landing/t-final.$h.state"
  printf 'revert-t-rev\tp\tc\t1\treverts-x\nt-gone\tp\tc\t1\tfull\n' > "$H/data/trunk-landings.tsv"
}
seed_home
obs() { OUT=$(bash "$OBS" "$@" 2>&1); RC=$?; }

# 1. The observer equals the crew-state reader on every state it can report, with no join evidence.
for w in working parked "done" blocked paused failed unknown; do
  obs "c-$w"; assert_equals "$w" "$OUT" "observer should equal jg-crew-state for $w"
done
obs h-open; assert_equals working "$OUT" "an open PR changes nothing"
obs h-closed; assert_equals "done" "$OUT" "a closed row with a merged PR is not stale"
# The real reader, in a home it cannot find a task in, gives the same word as the observer.
R=$T/real; mkdir -p "$R/state" "$R/config"; ln -sn "$ROOT/bin" "$R/bin"
want=$(JG_HOME=$R "$ROOT/bin/jg-crew-state.sh" ghost 2>/dev/null | sed -n 's/^state: \([a-z]*\) .*/\1/p')
OUT=$(JG_HOME=$R bash "$OBS" ghost 2>&1); assert_equals "$want" "$OUT" "observer equals the real jg-crew-state"
pass "the observer equals jg-crew-state on every fixture state"

# 1b. The trunk flow: a finished local-trunk lane is never "done"; a worker made ready again after a refusal is ready, not refused.
for w in t-ready1:ready-to-land t-ready2:ready-to-land t-land:landed t-clean:cleaned t-gone:cleaned t-final:rework t-rev:rework c-done:done; do
  obs "${w%%:*}"; assert_equals "${w#*:}" "$OUT" "trunk-flow state of ${w%%:*}"
done
jg_git_init_commit "$T/wt"
seed_task t-fixed "done" in_flight - - 'done [at=3]: ready in branch b'; printf 'mode=local-trunk\nworktree=%s\n' "$T/wt" >> "$H/state/t-fixed.meta"
printf 'final conflict\n' > "$H/data/jg-trunk-landing/t-fixed.$(printf 'b%.0s' {1..40}).state"
obs t-fixed; assert_equals ready-to-land "$OUT" "a refusal for an older head is not this head's"
obs --plain t-ready2; assert_equals "t-ready2: Finished; waits in the landing queue, #2" "$OUT" "queue place by finishing order"
pass "a finished local-trunk lane reads ready-to-land, landed, cleaned or rework, never done"

# 2. The join: row open and the work already landed, finished, or closed unmerged.
obs s-landed; assert_equals stale "$OUT" "a landing record with an open row is stale"
obs s-pr; assert_equals working "$OUT" "without --forge a PR state is not read"
obs s-pr --forge; assert_equals stale "$OUT" "an open row with a merged PR is stale"
obs a-21 --forge; assert_equals abandoned "$OUT" "an open row with a PR closed unmerged is abandoned"
obs f-1 --forge; assert_equals finished-elsewhere "$OUT" "a reported done with a merged PR is finished elsewhere"
obs sweep; assert_equals "$(printf 'stale\ts-landed')" "$OUT" "sweep without --forge lists only local evidence"
obs sweep --forge
assert_equals "3 abandoned 1 finished-elsewhere 3 stale" "$(printf '%s\n' "$OUT" | cut -f1 | sort | uniq -c | awk '{printf "%s%s %s",s,$1,$2;s=" "}')" \
  "sweep lists exactly 3 stale, 3 abandoned, 1 finished-elsewhere"
assert_not_contains "$OUT" "h-" "sweep lists no healthy task"
pass "sweep task lists the disagreeing rows and no healthy task"

# 3. The table: lint-clean, the engine reads the observer, and each state has its golden sentence.
bash "$JM" check task >"$T/lint" 2>&1; expect_code 0 "$?" "the task table lints clean"
OUT=$(bash "$JM" show task s-landed); assert_contains "$OUT" "state"$'\t'"stale" "the engine shows the observer's state"
OUT=$(bash "$JM" next task s-landed); assert_contains "$OUT" "bin/jg-backlog.sh done s-landed" "next names the owner command that closes the row"
# Every edge of the table is offered by `next` from a record in its from-state (the test id of each edge).
seed_task f-landed "done" in_flight - - 'done [at=2]: ready'; printf 'landed x\n' > "$H/data/jg-trunk-landing/f-landed.cafe.state"
fix_of() { case $1 in stale) echo s-landed ;; finished-elsewhere) echo f-landed ;; abandoned) echo a-21 ;; ready-to-land) echo t-ready1 ;; landed) echo t-land ;; rework) echo t-final ;; *) echo "c-$1" ;; esac; }
while IFS=$'\t' read -r kind from event to _; do
  [ "$kind" = edge ] || continue
  OUT=$(JG_MACHINE_FORGE=1 bash "$JM" next task "$(fix_of "$from")")
  assert_contains "$OUT" "move"$'\t'"$event"$'\t'"$to"$'\t' "next offers $from $event $to"
done < "$ROOT/core/machines/tables/task.tsv"
golden() { obs --plain "c-$1"; assert_equals "c-$1: $2" "$OUT" "plain sentence for $1"; }
golden working "The worker is working on it."
golden parked "The worker waits for a decision."
golden "done" "The worker finished a task that needs no landing."
golden blocked "The worker is stuck and needs help."
golden paused "The worker waits on purpose for something outside."
golden failed "The work failed."
golden unknown "No record says what this worker does now."
obs --plain s-landed; assert_equals "s-landed: The work is already merged but its backlog row is still open." "$OUT" "plain sentence for stale"
obs --plain a-21 --forge; assert_equals "a-21: The pull request was closed without a merge; the owner decides if the work is still wanted." "$OUT" "plain sentence for abandoned"
obs --plain f-1 --forge; assert_equals "f-1: The worker finished and the work is merged, but its backlog row is still open." "$OUT" "plain sentence for finished-elsewhere"
for w in t-land:"On the trunk; cleanup runs" t-clean:"On the trunk and cleaned up." t-final:"The lander named a conflict, or the suite found a red the commit caused and reverted it; the worker fixes it"; do
  obs --plain "${w%%:*}"; assert_equals "${w%%:*}: ${w#*:}" "$OUT" "plain sentence for ${w%%:*}"
done
pass "the task table is lint-clean and each state has a golden sentence"

# 4. The fleet view gets a State column only when config/machine-view exists; otherwise its output is unchanged.
cp "$ROOT/bin/jg-fleet-view.sh" "$H/bin/"; mkdir -p "$H/core"; ln -sn "$ROOT/core/machines" "$H/core/machines"
# shellcheck disable=SC2016  # the stand-in expands $JG_HOME when it runs
printf '#!/usr/bin/env bash\ncat "$JG_HOME/snapshot.json"\n' > "$H/bin/jg-fleet-snapshot.sh"; chmod +x "$H/bin/jg-fleet-snapshot.sh"
row='endpoint:{exists:true},pr:{url:null},paths:{home:{present:false},worktree:{present:false},report:{present:false}},actions:{watch:"w"},kind:"ship",backend:"tmux",backlog:{repo:"r"}'
jq -n "{schema:\"s\",jg_home:\"h\",backlog:{records:[]},squad_lead_current:{records:[]},squad_lead_guidance:{note:\"n\"},tasks:[
  {id:\"c-working\",current_state:{state:\"working\",source:\"pane\"},$row},{id:\"s-landed\",current_state:{state:\"unknown\",source:\"none\"},$row}]}" > "$H/snapshot.json"
view() { OUT=$(bash "$H/bin/jg-fleet-view.sh" 2>&1); RC=$?; }
view; expect_code 0 "$RC" "fleet view without the file"; base=$OUT
assert_contains "$base" "| ID | Current | Kind | Repo/Project | Backend | Endpoint | Artifact | Path | Watch / return channel |" "the header is unchanged"
assert_not_contains "$base" "State" "no State column without config/machine-view"
printf on > "$H/config/machine-view"; view; expect_code 0 "$RC" "fleet view with the file"
assert_contains "$OUT" "| Watch / return channel | State |" "the header gains a State column"
assert_contains "$OUT" "| c-working | working / pane |" "the row keeps its cells"
assert_contains "$(printf '%s\n' "$OUT" | grep '^| s-landed ')" "| The work is already merged but its backlog row is still open. |" "a stale task shows its captain sentence"
assert_equals "$base" "$(printf '%s\n' "$OUT" | sed -E '/^\| /s/ [^|]*\|$//')" \
  "removing the added column gives the output without the file"
pass "the fleet view shows the State column only when config/machine-view exists"
